import eslint from "@eslint/js";
import tseslint from "typescript-eslint";
import importX from "eslint-plugin-import-x";

export default tseslint.config(
  eslint.configs.recommended,
  ...tseslint.configs.recommended,
  {
    plugins: {
      "import-x": importX,
    },
    rules: {
      // Prevent circular imports between zones
      "import-x/no-cycle": ["error", { maxDepth: 3 }],

      // Enforce explicit engine barrel usage — block deep engine imports
      "import-x/no-restricted-paths": [
        "error",
        {
          zones: [
            {
              target: "./app/components/**",
              from: "./app/engine/!(index).ts",
              message: "Import from ~/engine barrel instead of engine internals.",
            },
            {
              target: "./app/routes/**",
              from: "./app/engine/!(index).ts",
              message: "Import from ~/engine barrel instead of engine internals.",
            },
            {
              target: "./app/hooks/**",
              from: "./app/engine/!(index).ts",
              message: "Import from ~/engine barrel instead of engine internals.",
            },
          ],
        },
      ],

      // Hooks should be imported from their barrel or individual files
      "import-x/no-duplicates": "warn",

      // Allow unused vars prefixed with _
      "@typescript-eslint/no-unused-vars": [
        "warn",
        { argsIgnorePattern: "^_", varsIgnorePattern: "^_" },
      ],
    },
  },
  {
    ignores: ["build/**", "node_modules/**", ".react-router/**"],
  },
);

import { defineConfig } from "vitest/config";
import tsconfigPaths from "vite-tsconfig-paths";

export default defineConfig({
  plugins: [tsconfigPaths()],
  test: {
    include: ["app/**/*.test.ts"],
  },
});

import { describe, it, expect } from "vitest";
import { posKey } from "./utils";

describe("posKey", () => {
  it("returns 'row,col' format", () => {
    expect(posKey(0, 0)).toBe("0,0");
    expect(posKey(3, 7)).toBe("3,7");
  });

  it("handles negative coordinates", () => {
    expect(posKey(-1, -2)).toBe("-1,-2");
  });

  it("produces unique keys for distinct positions", () => {
    const keys = new Set([posKey(1, 2), posKey(2, 1), posKey(1, 1)]);
    expect(keys.size).toBe(3);
  });
});

import { describe, it, expect } from "vitest";
import {
  simulateTraversal,
  opposite,
  getConnection,
  getExitSide,
} from "./traversal";
import type { LevelData, PlacedTile, Direction, Rotation } from "./types";
import { NORTH, EAST, SOUTH, WEST } from "./types";
import { posKey } from "./utils";

// Minimal level factory for testing
function makeLevel(overrides: Partial<LevelData> = {}): LevelData {
  return {
    id: "test",
    worldId: 1,
    levelIndex: 0,
    name: "Test",
    width: 6,
    height: 6,
    start: { row: 2, col: 0, direction: EAST },
    goal: { row: 2, col: 3 },
    obstacles: [],
    inventory: { straight: 3, curve: 0 },
    par: 2,
    biome: "meadow",
    ...overrides,
  };
}

function tile(type: "straight" | "curve", rotation: Rotation): PlacedTile {
  return { type, rotation };
}

describe("opposite", () => {
  it("returns the opposite direction", () => {
    expect(opposite(NORTH)).toBe(SOUTH);
    expect(opposite(SOUTH)).toBe(NORTH);
    expect(opposite(EAST)).toBe(WEST);
    expect(opposite(WEST)).toBe(EAST);
  });
});

describe("getConnection", () => {
  it("straight at rotation 0 connects NORTH-SOUTH", () => {
    const [a, b] = getConnection("straight", 0 as Rotation);
    expect(new Set([a, b])).toEqual(new Set([NORTH, SOUTH]));
  });

  it("straight at rotation 1 connects EAST-WEST", () => {
    const [a, b] = getConnection("straight", 1 as Rotation);
    expect(new Set([a, b])).toEqual(new Set([EAST, WEST]));
  });

  it("curve at rotation 0 connects SOUTH-EAST", () => {
    const [a, b] = getConnection("curve", 0 as Rotation);
    expect(new Set([a, b])).toEqual(new Set([SOUTH, EAST]));
  });
});

describe("getExitSide", () => {
  it("returns the other side for a valid entry", () => {
    // straight rotation 0: NORTH-SOUTH
    expect(getExitSide("straight", 0 as Rotation, NORTH)).toBe(SOUTH);
    expect(getExitSide("straight", 0 as Rotation, SOUTH)).toBe(NORTH);
  });

  it("returns null for an invalid entry side", () => {
    // straight rotation 0 only connects NORTH-SOUTH
    expect(getExitSide("straight", 0 as Rotation, EAST)).toBeNull();
  });
});

describe("simulateTraversal", () => {
  it("reaches goal with correct straight tiles", () => {
    const level = makeLevel();
    const tiles = new Map<string, PlacedTile>();
    // Place two straight tiles (horizontal: rotation 1) from (2,1) to (2,2)
    tiles.set(posKey(2, 1), tile("straight", 1 as Rotation));
    tiles.set(posKey(2, 2), tile("straight", 1 as Rotation));

    const result = simulateTraversal(level, tiles);
    expect(result.success).toBe(true);
    expect(result.outcome).toBe("goal");
  });

  it("returns 'no-path' when tiles are missing", () => {
    const level = makeLevel();
    const tiles = new Map<string, PlacedTile>();
    // No tiles placed — Lucky walks into empty cell

    const result = simulateTraversal(level, tiles);
    expect(result.success).toBe(false);
    expect(result.outcome).toBe("no-path");
  });

  it("returns 'edge' when path leads out of bounds", () => {
    const level = makeLevel({
      start: { row: 0, col: 2, direction: NORTH },
      goal: { row: 5, col: 5 },
    });
    const tiles = new Map<string, PlacedTile>();
    // Lucky faces NORTH at row 0, immediately walks off the edge

    const result = simulateTraversal(level, tiles);
    expect(result.success).toBe(false);
    expect(result.outcome).toBe("edge");
  });

  it("returns 'obstacle' when path hits an obstacle", () => {
    const level = makeLevel({
      obstacles: [{ row: 2, col: 1 }],
    });
    const tiles = new Map<string, PlacedTile>();
    // Lucky faces EAST at (2,0) and steps into obstacle at (2,1)

    const result = simulateTraversal(level, tiles);
    expect(result.success).toBe(false);
    expect(result.outcome).toBe("obstacle");
  });

  it("returns 'blocked' when tile cannot be entered from the given direction", () => {
    const level = makeLevel();
    const tiles = new Map<string, PlacedTile>();
    // Place a straight tile at (2,1) but with vertical orientation (rotation 0)
    // Lucky enters from WEST side but straight-0 only connects NORTH-SOUTH
    tiles.set(posKey(2, 1), tile("straight", 0 as Rotation));

    const result = simulateTraversal(level, tiles);
    expect(result.success).toBe(false);
    expect(result.outcome).toBe("blocked");
  });

  it("returns 'loop' when Lucky enters a cycle", () => {
    // Create a 4x4 loop with curves
    const level = makeLevel({
      width: 6,
      height: 6,
      start: { row: 2, col: 0, direction: EAST },
      goal: { row: 5, col: 5 }, // unreachable
    });
    const tiles = new Map<string, PlacedTile>();
    // Build a loop: (2,1) → (1,1) → (1,2) → (2,2) → (2,1)
    // curve rot 3: connects WEST-NORTH (enter from WEST, exit NORTH)
    tiles.set(posKey(2, 1), tile("curve", 3 as Rotation));
    // curve rot 2: connects NORTH-WEST → actually WEST-NORTH
    // At (1,1), Lucky enters from SOUTH. Need: SOUTH-EAST connection
    // curve rot 1: connects WEST-SOUTH → no. Let me think...
    // curve base: SOUTH-EAST at rot 0
    // rot 0: SOUTH-EAST — enter from SOUTH, exit EAST ✓
    tiles.set(posKey(1, 1), tile("curve", 0 as Rotation));
    // At (1,2), Lucky enters from WEST. Need: WEST-SOUTH
    // curve rot 3: WEST-NORTH. curve rot 1: EAST-SOUTH. curve rot 2: NORTH-WEST.
    // Wait: rot 1 = base + 1 = (SOUTH+1, EAST+1) = (WEST, SOUTH)
    // enter from WEST, exit SOUTH ✓
    tiles.set(posKey(1, 2), tile("curve", 1 as Rotation));
    // At (2,2), Lucky enters from NORTH. Need: NORTH-WEST
    // rot 2 = base + 2 = (SOUTH+2, EAST+2) = (NORTH, WEST) ✓
    tiles.set(posKey(2, 2), tile("curve", 2 as Rotation));

    const result = simulateTraversal(level, tiles);
    expect(result.success).toBe(false);
    expect(result.outcome).toBe("loop");
  });

  it("handles curve tile navigation to goal", () => {
    const level = makeLevel({
      start: { row: 2, col: 0, direction: EAST },
      goal: { row: 0, col: 2 },
    });
    const tiles = new Map<string, PlacedTile>();
    // (2,1): straight horizontal (rotation 1)
    tiles.set(posKey(2, 1), tile("straight", 1 as Rotation));
    // (2,2): curve that turns WEST→NORTH = enter from WEST, exit NORTH
    // curve rot 3: (SOUTH+3, EAST+3) = (WEST, NORTH)? Let's see...
    // base connections: [SOUTH, EAST] at rot 0
    // rot 3: [(SOUTH+3)%4, (EAST+3)%4] = [WEST, NORTH]
    // enter from WEST, exit NORTH ✓
    tiles.set(posKey(2, 2), tile("curve", 3 as Rotation));
    // (1,2): straight vertical (rotation 0: NORTH-SOUTH)
    tiles.set(posKey(1, 2), tile("straight", 0 as Rotation));

    const result = simulateTraversal(level, tiles);
    expect(result.success).toBe(true);
    expect(result.outcome).toBe("goal");
    // Path should be: (2,0) → (2,1) → (2,2) → (1,2) → (0,2)
    expect(result.path.length).toBe(5);
  });
});

